import java.util.*;

class CustomStack {
    private int[] stack, inc;  // inc[i]: boost for element i and everything below it
    private int size = 0;

    public CustomStack(int maxSize) {
        stack = new int[maxSize];
        inc = new int[maxSize];
    }

    public void push(int x) {
        if (size < stack.length) stack[size++] = x;   // ignore when full
    }

    public int pop() {
        if (size == 0) return -1;
        int i = size - 1;
        int res = stack[i] + inc[i];
        if (i > 0) inc[i - 1] += inc[i];              // pass the boost down
        inc[i] = 0;                                   // clear for future pushes
        size--;
        return res;
    }

    public void increment(int k, int val) {
        int i = Math.min(k, size) - 1;
        if (i >= 0) inc[i] += val;                    // lazy: mark only the top of the range
    }
}

