class CustomStack:
    def __init__(self, maxSize: int):
        self.n = maxSize; self.s = []; self.inc = []
    def push(self, x: int) -> None:
        if len(self.s) < self.n: self.s.append(x); self.inc.append(0)
    def pop(self) -> int:
        if not self.s: return -1
        add = self.inc.pop()
        if self.inc: self.inc[-1] += add
        return self.s.pop() + add
    def increment(self, k: int, val: int) -> None:
        if self.s: self.inc[min(k, len(self.s)) - 1] += val

